function resultSummary(p,h){const states=p.history.flatMap(h=>h.state),events=p.history.flatMap(h=>h.events),care=p.history.flatMap(h=>h.care),high=h.state.filter(s=>s.health<40),first=p.history.find(h=>h.state.some(s=>s.health<40)),worst=p.history.slice().sort((a,b)=>a.state.reduce((n,p)=>n+p.health,0)-b.state.reduce((n,p)=>n+p.health,0))[0],freq={};events.forEach(e=>freq[e.dominant]=(freq[e.dominant]||0)+1);const dominant=Object.entries(freq).sort((a,b)=>b[1]-a[1])[0]?.[0],label=D.graph.nodes.find(n=>n.id===dominant)?.label||'无显著风险',exec=care.filter(c=>c.decision==='执行');const rows=[['map','地图',`C${h.cycle} · 健康${(h.state.reduce((n,s)=>n+s.health,0)/h.state.length).toFixed(1)}`,`${high.length}个高风险对象 · ${new Set(high.map(s=>s.area)).size}个区域`],['timeline','时间线',`${events.length}项事件`,`${p.horizon}个月 · 首次高风险${first?'C'+first.cycle:'无'} · 最严重C${worst.cycle}`],['risks','风险',`${events.filter(e=>['high','critical'].includes(e.severity)).length}次严重事件`,`${p.horizon}个月 · 暴露${(states.filter(s=>s.health<40).length/states.length*100).toFixed(1)}% · ${label}`],['care','养护',`${exec.length}次执行 · ${money(exec.reduce((n,c)=>n+c.cost,0))}`,`${p.horizon}个月 · 资源不足${care.filter(c=>c.decision==='资源不足').length}次 · ${exec.reduce((n,c)=>n+c.waterM3,0).toFixed(1)}m³ / ${exec.reduce((n,c)=>n+c.laborHours,0).toFixed(1)}工时`]];return `<div class="summary-grid">${rows.map(([id,title,value,note])=>`<button class="summary-card ${U.tab===id&&U.resultOpen?'selected':''}" data-act="result-expand" data-tab="${id}" aria-expanded="${U.tab===id&&!!U.resultOpen}">${icon(id)}<strong>${title}</strong><b>${value}</b><small>${note}</small><span>${U.tab===id&&U.resultOpen?'收起记录 −':'查看详情 ＋'}</span></button>`).join('')}</div>`;}
function costPanel(rows){const scope=U.costScope||'all',data=rows.map(r=>({...r,cost:B.costs(r.run,scope)})),selected=data.find(r=>r.version===U.costVersion)||data[0],keys=[['construction','建设','#a4d4c5'],['maintenance','养护','#b8a4ed'],['rework','预计返工','#ffb084']],max=Math.max(1,...data.map(r=>r.cost.construction+r.cost.maintenance+r.cost.rework)),groups={};selected.cost.items.forEach(i=>groups[i.category]=(groups[i.category]||0)+i.amount);const total=selected.cost.construction,palette=['#a4d4c5','#b8a4ed','#ffb084','#e8b94a','#9ab7b2','#ff6b5a'];let offset=0;return `<section class="section card cost-panel"><div class="section-head"><div><h2>${icon('cost')} 成本对比</h2><p class="tiny">单位：元 · 建设＋${scope==='all'?'六种未来的平均':'路径'+scope}养护及预计返工</p></div><label>费用范围<select id="costScope"><option value="all" ${scope==='all'?'selected':''}>六种未来的平均</option>${E.PATHS.map(p=>`<option value="${p.id}" ${scope===p.id?'selected':''}>${p.id} ${p.name}</option>`).join('')}</select></label></div>${costExplanation(data,scope)}<div class="cost-stacks">${data.map(r=>`<div class="cost-stack-row"><b>${r.version}</b><div class="cost-stack" style="width:${(r.cost.construction+r.cost.maintenance+r.cost.rework)/max*100}%">${keys.map(([k,label,color])=>`<button data-act="cost-detail" data-run="${r.run.id}" data-category="${k}" style="flex:${r.cost[k]};background:${color}" aria-label="${r.version}${label}${money(r.cost[k])}">${r.cost[k]/(r.cost.construction+r.cost.maintenance+r.cost.rework)>.1?money(r.cost[k]):''}</button>`).join('')}</div><strong>${money(r.cost.construction+r.cost.maintenance+r.cost.rework)}</strong><small class="cost-row-label">${keys.map(([k,label])=>label+' '+money(r.cost[k])).join(' · ')}</small></div>`).join('')}</div><div class="legend">${keys.map(([key,label,color])=>`<button class="btn small" data-act="cost-detail" data-run="${selected.run.id}" data-category="${key}"><i style="background:${color}"></i>${label}</button>`).join('')}</div><div class="grid two section"><div><label>建设费用构成<select id="costVersion">${data.map(r=>`<option ${r.version===selected.version?'selected':''}>${r.version}</option>`).join('')}</select></label><svg class="cost-donut" viewBox="0 0 300 240" role="group" aria-label="建设费用构成环形图">${Object.entries(groups).map(([name,value],i)=>{const start=offset;offset+=total?value/total*100:0;return `<circle role="button" tabindex="0" data-act="cost-detail" data-run="${selected.run.id}" data-category="${esc(name)}" aria-label="${esc(name)} ${money(value)}" cx="150" cy="115" r="80" fill="none" stroke="${palette[i%palette.length]}" stroke-width="34" pathLength="100" stroke-dasharray="${total?value/total*100:0} 100" stroke-dashoffset="${-start}" transform="rotate(-90 150 115)"/>`;}).join('')}<text x="150" y="112" text-anchor="middle">${money(total)}</text><text x="150" y="135" text-anchor="middle">${selected.version} 建设投入</text></svg><div class="cost-legend">${Object.entries(groups).map(([name,value],i)=>btn(`<i style="background:${palette[i%palette.length]}"></i>${name} ${money(value)} · ${total?(value/total*100).toFixed(1):0}%`,'cost-detail',`data-run="${selected.run.id}" data-category="${name}"`)).join('')}</div></div><div><h3>后续养护支出</h3>${selected.cost.categories.map((cat,i)=>{const maxCat=Math.max(1,...data.map(r=>r.cost.categories[i].amount));return `<div class="care-cost-group"><b>${cat.name}</b>${data.map((r,j)=>`<button class="care-cost-bar" data-act="cost-detail" data-run="${r.run.id}" data-category="${cat.name}"><span>${r.version}</span><span class="track"><i style="width:${r.cost.categories[i].amount/maxCat*100}%;background:${palette[j]}"></i></span><span>${money(r.cost.categories[i].amount)}</span></button>`).join('')}</div>`;}).join('')}</div></div><details><summary>查看费用数据表</summary><div class="table-wrap"><table class="table"><thead><tr><th>方案</th><th>建设</th><th>养护</th><th>预计返工</th><th>合计</th></tr></thead><tbody>${data.map(r=>`<tr><td>${r.version}</td><td>${money(r.cost.construction)}</td><td>${money(r.cost.maintenance)}</td><td>${money(r.cost.rework)}</td><td>${money(r.cost.construction+r.cost.maintenance+r.cost.rework)}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
