function archiveHome(){const profile=platformProfile(),enterprise=U.auth?.type!=='personal',visible=enterprise?archives:[];return `<section class="section platform-value"><div class="section-head"><div><div class="eyebrow">${enterprise?'组织价值':'个人价值'}</div><h2>每次评测，积累价值。</h2></div>${badge(enterprise?'企业数据看板':'个人数据看板')}</div><div class="grid">${[['cost','累计节省成本',money(profile.value.cost),'净节省'],['timeline','累计节约评审工时',profile.value.hours.toLocaleString()+'小时','累计工时'],['done','已完成项目',profile.value.projects.toLocaleString()+'项','累计']].map(([id,title,value,sub])=>`<button class="feature ${id==='cost'?'teal':id==='timeline'?'lav':'peach'}" data-act="value-details" data-value-metric="${id}">${icon(id)}<h3>${title}</h3><div class="metric">${value}</div><small>${sub} · 查看日 / 周 / 月趋势 ↗</small></button>`).join('')}</div><div class="section-head recent-projects"><h3>最近项目成果</h3></div><div class="grid">${visible.map(a=>`<article class="card">${badge('已完成','normal')}<h3>${esc(a.project.name)}</h3><p>${a.adoption.versionId} · ${new Date(a.completedAt).toLocaleDateString('zh-CN')}</p><p>${a.contribution.cost<0?'增加投入':'节省成本'} ${money(Math.abs(a.contribution.cost))}</p>${btn('查看成果','open-archive',`data-id="${a.id}"`,true)}</article>`).join('')||'<p>暂无已完成项目。</p>'}</div></section>`;}
const homeBefore=home;home=function(){return homeBefore().replace('<section class="section">',archiveHome()+'<section class="section">').replace('刷新后重新开始','当前演示会话').replace('让受控 Agent 连续模拟','对比不同未来情景').replace(/<div class="mini">确定性 Workflow \+ 受控 Agent<\/div>/g,'').replace('条件 → Effect → 状态','发现问题 → 定位原因').replace('Checkpoint → 局部恢复','查看过程 → 决策留档') .replace('并行路径 · 顺序周期','多个未来 · 长期表现').replace(badge(version().status),badge(P.status==='completed'?'已完成':version().status)).replace('异构资料','项目资料').replace('输入冲突 → 标准基线','核对资料 → 确认方案').replace('目标 → 6张冻结任务卡','设计目标 → 六种未来情景');};
