const causeBefore=cause;cause=function(h,plant,technical=true){if(!h.effects)return `<p>归档结果保留逐周期植物状态；完整原因链需同条件重跑。</p>`;return causeBefore(h,plant,technical);};
const traceBefore=traceView;traceView=function(){if(run()?.archived)return `${header('项目成果','已归档 · 结果与决策只读')}<p>完整节点记录需同条件重跑。</p>${btn('继续优化','continue-project','',true)} ${btn('导出项目归档','export-archive')}${summary()}${hoursEditor()}`;return traceBefore()+hoursEditor()+(P.status==='completed'?btn('继续优化','continue-project','',true):B.completionIssues(P).length?`<div class="card"><h3>完成项目还需要</h3><p>${B.completionIssues(P).join('；')}</p>${btn('前往方案采纳','completion-adopt')}</div>`:'');};
function projectOverview(){const formal=P.runs.filter(r=>!r.replayOf),completed=formal.filter(r=>r.status==='complete'),latest=E.latestRun(P,U.version)||completed.at(-1),histories=completed.flatMap(r=>r.paths.flatMap(p=>p.history||[])),riskEvents=histories.flatMap(h=>h.events||[]),care=histories.flatMap(h=>h.care||[]),executed=care.filter(c=>c.decision==='执行'),recovered=formal.flatMap(r=>r.failures||[]).filter(f=>f.status==='RECOVERED').length,frozen=P.cards.filter(c=>c.frozen).length,issues=B.completionIssues(P);let evaluation=null;try{evaluation=latest?.evaluation||(latest?.status==='complete'?E.evaluate(latest):null);}catch{}const stages=[[1,'项目资料',version().baseline.confirmed,`${P.imports.length}份资料 · ${version().baseline.plants.length}条植物记录`],[2,'模拟目标',P.goals.length>0,`${P.goals.length}个目标版本 · ${P.messages.filter(m=>m.kind==='goal').length}条对话`],[3,'未来蓝图',frozen===P.cards.length&&frozen>0,`${frozen}/${P.cards.length}条路径已冻结`],[4,'模拟运行',completed.length>0,`${completed.length}次正式完成 · ${P.runs.length-completed.length}次运行中/回放`],[5,'结果与风险',riskEvents.length>0,`${riskEvents.length}项风险 · ${executed.length}次养护执行`],[6,'方案比较',P.versions.filter(v=>E.latestRun(P,v.id)).length>=2,`${P.versions.length}个设计版本 · ${P.versions.reduce((n,v)=>n+v.layoutChanges.length,0)}项空间变更`],[7,'评审决策',(P.decisions||[]).length>0,`${(P.decisions||[]).length}次评审 · ${P.adoption?'已采纳'+P.adoption.versionId:'尚未采纳'}`]],done=stages.filter(s=>s[2]).length,progress=Math.round(done/stages.length*100),status=P.status==='completed'?'已完成':P.adoption?'待结项':completed.length?'评审中':'进行中',adoption=P.adoption,latestVersion=latest?.versionId||U.version;return `${header('项目总览','')}<section class="overview-hero"><div><span class="overview-status">${status}</span><h2>${esc(P.name)}</h2><p>${esc(P.location)} · ${P.area}公顷 · 当前方案 ${esc(latestVersion)}</p><div class="overview-actions">${btn(P.status==='completed'?'返回工作台':'继续当前工作','nav',`data-page="${P.status==='completed'?0:(stages.find(s=>!s[2])?.[0]||7)}"`,true)}${btn('查看运行记录','nav','data-page="7"')}</div></div><div class="overview-progress" style="--progress:${progress*3.6}deg"><strong>${progress}%</strong><span>${done}/${stages.length}项完成</span></div></section><section class="section"><div class="section-head"><div><h2>项目进展</h2><p>从资料确认到评审决策的实际完成情况</p></div></div><div class="overview-timeline">${stages.map(([page,label,ok,note],i)=>`<button data-act="nav" data-page="${page}" class="${ok?'done':i===done?'current':''}"><span>${ok?'✓':String(i+1).padStart(2,'0')}</span><strong>${label}</strong><small>${note}</small></button>`).join('')}</div></section><section class="section"><div class="section-head"><div><h2>工作成果</h2><p>当前项目累计形成的业务记录</p></div></div><div class="overview-stats">${[['plants','资料与植物',`${P.imports.length} / ${version().baseline.plants.length}`,'资料 / 植物记录'],['timeline','正式模拟',completed.length,'完成运行'],['risks','风险发现',riskEvents.length,'风险事件'],['care','养护执行',executed.length,'实际执行动作'],['stability','方案版本',P.versions.length,'独立设计版本'],['done','异常恢复',recovered,'已恢复节点']].map(([ico,label,value,unit])=>`<article class="overview-stat">${icon(ico)}<span>${label}</span><strong>${value}</strong><small>${unit}</small></article>`).join('')}</div></section><section class="section grid two overview-main"><article class="card"><div class="section-head"><div><h2>方案与运行</h2><p>各版本修改、模拟和评价状态</p></div></div><div class="overview-version-list">${P.versions.map(v=>{const r=E.latestRun(P,v.id),ev=r?.evaluation;return `<button data-act="version" data-version="${v.id}"><span><b>${v.id}</b>${badge(v.status)}</span><strong>${esc(v.note)}</strong><small>${v.layoutChanges.length}项设计变更 · ${r?r.id+' / '+r.status:'未运行'}</small>${ev?`<em>${ev.dimensions.map(d=>`${esc(d.name)} ${d.score==null?'—':d.score.toFixed(1)}`).join(' · ')}</em>`:''}</button>`;}).join('')}</div></article><article class="card overview-evaluation"><div class="section-head"><div><h2>当前五维表现</h2><p>${latest?`${latest.versionId} · ${latest.id}`:'完成模拟后生成'}</p></div></div>${evaluation?evaluation.dimensions.map(d=>`<div class="overview-score">${icon(d.id)}<span>${esc(d.name)}</span><div class="progress"><i style="width:${d.score||0}%"></i></div><b>${d.score==null?'—':d.score.toFixed(1)}</b></div>`).join(''):'<div class="overview-empty">尚无完整评价结果</div>'}</article></section><section class="section card overview-decision"><div><h2>${adoption?'评审结论':'项目待办'}</h2>${adoption?`<p class="decision-lead">${esc(adoption.versionId)} · ${esc(decisionLabels[adoption.outcome]||'已记录')}</p><p>${esc(adoption.note)}</p><p><b>保留风险与取舍：</b>${esc(adoption.risks)}</p><small>${esc(adoption.reviewer)} · ${new Date(adoption.at).toLocaleString('zh-CN')}</small>`:`<p class="decision-lead">${issues.length}项工作尚未完成</p><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}</div><div class="overview-decision-actions">${btn('查看方案比较','nav','data-page="6"')}${P.status==='completed'?btn('返回工作台','nav','data-page="0"',true):btn('完成项目，返回工作台','complete-project','',true)}</div></section>`;}
const modifyBefore=modify;modify=function(){if(P.status==='completed')return toast('已完成项目只读，请点击继续优化');modifyBefore();if(!$('#modifyFull'))return;const resilient=version().strategy==='balanced'||version().strategy==='resilient';$('#modifyFull').checked=resilient;$('#modifyFull').parentElement.lastChild.textContent=' 韧性强化：排水、抗风支撑、扩展保护与应急供水（基础均衡优化始终包含）';$('#modifyNote').value=B.PRESETS[resilient?'resilient':'balanced'].note;updatePreview();};
updatePreview=function(){if(!$('#modifyPreview'))return;if(!Number.isFinite(+$('#modifySpacing').value)||+$('#modifySpacing').value<1||+$('#modifySpacing').value>10){$('#modifyPreview').textContent='请输入1–10米的间距';return;}const fake=E.clone({...P,runs:[]});fake.status='active';const v=E.createVersion(fake,fake.versions.find(v=>v.id===U.version),{strategy:$('#modifyFull').checked?'resilient':'balanced',species:$('#modifySpecies').value,spacing:+$('#modifySpacing').value});$('#modifyPreview').innerHTML=`<strong>${B.PRESETS[v.strategy].name}</strong><p>${esc(B.PRESETS[v.strategy].note)}</p><p>建设投入 ${money(v.cost)} · ${v.layoutChanges.length}项变更</p>${map(v.baseline.plants)}`;};
function downloadArchive(item){const blob=new Blob([JSON.stringify(item)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='plantsim-archive-'+item.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function finishProject(){const issues=B.completionIssues(P);if(issues.length){modal('完成项目还需要',`<ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,btn('返回','close')+btn('前往方案采纳','completion-adopt','',true));return;}if(P.status==='completed'){route(0);return;}pendingArchive=B.archive(P);try{archives=B.save(localStorage,archives,pendingArchive);storageError='';P.status='completed';P.completedAt=pendingArchive.completedAt;stop();clearInterval(autoTimer);autoTimer=null;U.auto=false;U.autoIndex=0;U.autoRemaining=20;route(0);toast('项目已完成，成果已保存到本地');}catch(e){storageError=e.message;modal('尚未保存成功','<p>本地空间不足或浏览器禁止存储。当前成果仍在内存，可先导出备份再重试。</p>',btn('导出归档','export-archive')+btn('重试保存','complete-project','',true));}}
const presentationAct=act;act=function(a,b={}){const writes=['create-version','confirm-baseline','import','conflict','save-goal','restore-goal','freeze','unfreeze','freeze-all','validate-card','adopt','create-run','rerun','replay','save-hours','bad'];if(P.status==='completed'&&writes.includes(a))return toast('项目已完成，请先继续优化');switch(a){
case 'result-expand':U.resultOpen=U.tab===b.tab?!U.resultOpen:true;U.tab=b.tab;render();return;
case 'path':U.resultOpen=false;break;
case 'dimensions-all':U.openDimensions=b.value==='open'?D.DEFINITIONS.map(x=>x[0]):[];render();return;
case 'complete-project':close();finishProject();return;case 'completion-adopt':close();route(6);return;
case 'save-hours':P.hours=(P.hours||B.HOURS).map((h,i)=>({...h,traditional:+$('#hours-old-'+i).value,assisted:+$('#hours-new-'+i).value}));if(P.hours.some(h=>h.traditional<0||h.assisted<0))throw Error('工时不能为负数');toast('工时估算已保存');return;
case 'open-archive':{pendingArchive=null;const item=archives.find(x=>x.id===b.id);if(!item)return;stop();clearInterval(autoTimer);autoTimer=null;P=B.restore(item);U.auto=false;U.autoIndex=0;U.version=P.adoption.versionId;U.runId=P.adoption.runId;U.mode='business';U.resultOpen=false;route(7);return;}
case 'continue-project':{P.status='active';const base=version();P.adoption=null;const v=E.createVersion(P,base,{strategy:'resilient'});U.version=v.id;U.runId=null;route(1);toast('已创建后续修订；原归档仍保留');return;}
case 'export-archive':{const item=pendingArchive||archives.find(x=>x.id===P.id);if(!item)return toast('暂无可导出的归档');downloadArchive(item);return;}
case 'value-details':{const values=B.totals(archives);modal('累计价值明细',`<p>成本按原方案减采纳方案计算，增加投入以负贡献计入。工时为评审工作量估算。</p><div class="table-wrap"><table class="table"><tr><th>项目/来源</th><th>原方案</th><th>采纳方案</th><th>净节省</th><th>节约工时</th></tr>${values.rows.map(r=>`<tr><td>${esc(r.name)}<small>${r.source}</small></td><td>${money(r.baseCost)}</td><td>${money(r.chosenCost)}</td><td>${r.cost<0?'增加投入 '+money(-r.cost):money(r.cost)}</td><td>${r.hours}小时</td></tr>`).join('')}</table></div><details><summary>查看案例与工时原始口径</summary>${json(values.rows)}</details>`,btn('关闭','close'));return;}
case 'cost-detail':{const r=P.runs.find(r=>r.id===b.run),c=B.costs(r,U.costScope||'all'),cat=c.categories.find(x=>x.name===b.category),items=b.category==='construction'?c.items:c.items.filter(x=>x.category===b.category),records=b.category==='maintenance'?c.categories.flatMap(x=>x.records):cat?.records;modal('费用明细 · '+b.category,items.length?`<div class="table-wrap"><table class="table"><tr><th>费用/对象</th><th>数量</th><th>单价</th><th>金额</th></tr>${items.map(i=>`<tr><td>${esc(i.category)} / ${esc(i.target)}</td><td>${i.quantity}${i.unit}</td><td>${money(i.unitPrice)}</td><td>${money(i.amount)}</td></tr>`).join('')}</table></div>`:records?`<p>执行${records.length}次；费用含人工与材料，不重复计费。六种未来的平均为动作总费用除以6。</p><div class="table-wrap"><table class="table"><tr><th>来源</th><th>措施</th><th>次数×单价</th></tr>${records.map(x=>`<tr><td>${x.path}/C${x.cycle}/${x.plant}</td><td>${esc(x.action)}</td><td>1×${money(x.cost)}</td></tr>`).join('')}</table></div>`:json(c.reworkRows),btn('关闭','close'));return;}
case 'graph-evidence':if(E.latestRun(P,U.version)?.archived)return toast('归档不包含Effect，请继续优化并同条件重跑');break;
case 'replay':if(run()?.archived)return toast('归档不含节点Checkpoint，请同条件重跑');break;
}return presentationAct(a,b);};
document.addEventListener('change',e=>{if(e.target.id==='costScope'){U.costScope=e.target.value;render();}if(e.target.id==='costVersion'){U.costVersion=e.target.value;render();}});
/* Review refinements: explicit scenarios, synchronized map navigation and decision records. */
function scenarioComparison(rows){return `<section class="section"><h2>不同未来下的表现</h2><p>同一方案遇到不同天气与人流，植物能否保持健康？分别查看每种未来的健康水平和高风险负担。</p><div class="grid">${rows.map(r=>`<article class="card"><h3>${r.version}</h3>${r.evaluation.perPath.map(p=>`<div class="scenario-row"><strong>${p.pathId} · ${esc(E.PATHS.find(x=>x.id===p.pathId)?.name||'')}</strong><div>平均健康 <b>${p.health.toFixed(1)}</b> / 100</div><div class="progress"><span style="width:${p.health}%"></span></div><div>高风险植物月占比 <b>${p.exposure.toFixed(1)}%</b></div></div>`).join('')}<p>最需关注：${esc(E.PATHS.find(p=>p.id===r.evaluation.perPath.slice().sort((a,b)=>a.health-b.health)[0].pathId)?.name||'')}</p></article>`).join('')}</div><details><summary>这两个数值如何理解？</summary><p>平均健康：36个月内全部植物记录的健康分平均值。高风险植物月占比：健康低于40分的植物月记录占全部植物月记录的比例。例如一株植物连续两个月高风险，计为两个植物月；该比例不是灾害发生概率。</p></details></section>`;}
function costExplanation(data,scope){return `<div class="cost-explanation"><p>${scope==='all'?'每个方案的柱形是平均全周期成本：建设计一次，养护与预计返工分别取六种未来的平均；不是六种未来成本相加。':'当前柱形：建设费用＋所选未来36个月养护费用＋该未来预计返工费用。'}</p>${scope==='all'?`<details><summary>查看六种未来的金额与平均计算</summary>${data.map(r=>{const cs=r.run.paths.map(p=>({id:p.id,...B.costs(r.run,p.id)}));return `<h4>${r.version} · 建设 ${money(r.cost.construction)}（只计一次）</h4><table class="table"><thead><tr><th>未来</th><th>养护</th><th>预计返工</th><th>全周期合计</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${c.id}</td><td>${money(c.maintenance)}</td><td>${money(c.rework)}</td><td>${money(c.construction+c.maintenance+c.rework)}</td></tr>`).join('')}</tbody></table><p>养护：${money(cs.reduce((n,c)=>n+c.maintenance,0))} ÷ ${cs.length} = ${money(r.cost.maintenance)}；预计返工：${money(cs.reduce((n,c)=>n+c.rework,0))} ÷ ${cs.length} = ${money(r.cost.rework)}</p>`;}).join('')}</details>`:''}</div>`;}
mapControls=function(){return `<div class="map-console" role="group" aria-label="同步地图导航"><div class="map-pad">${btn('↑','pan','data-y="-20" aria-label="地图上移"')}${btn('←','pan','data-x="-30" aria-label="地图左移"')}${btn('⌂','map-reset','aria-label="地图复位"')}${btn('→','pan','data-x="30" aria-label="地图右移"')}${btn('↓','pan','data-y="20" aria-label="地图下移"')}</div><div class="map-zoom">${btn('−','zoom','data-value="-0.25" aria-label="缩小地图"')}<input data-map-zoom type="range" min="100" max="250" step="5" value="${Math.round(U.zoom*100)}" aria-label="地图缩放比例">${btn('＋','zoom','data-value="0.25" aria-label="放大地图"')}<output data-map-percent>${Math.round(U.zoom*100)}%</output><small>滚轮缩放 · 拖动平移 · 多图同步</small></div></div>`;};
function syncMaps(){const w=760/U.zoom,h=400/U.zoom;document.querySelectorAll('.map svg').forEach(s=>s.setAttribute('viewBox',[(760-w)/2+U.panX,(400-h)/2+U.panY,w,h].join(' ')));document.querySelectorAll('[data-map-percent]').forEach(x=>x.textContent=Math.round(U.zoom*100)+'%');document.querySelectorAll('[data-map-zoom]').forEach(x=>x.value=Math.round(U.zoom*100));}
document.addEventListener('input',e=>{if(e.target.matches('[data-map-zoom]')){U.zoom=+e.target.value/100;syncMaps();}});
document.addEventListener('wheel',e=>{if(!e.target.closest('.map svg'))return;e.preventDefault();U.zoom=Math.max(1,Math.min(2.5,U.zoom+(e.deltaY<0?.1:-.1)));syncMaps();},{passive:false});
let mapDrag=null,mapDragged=false;
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('.map svg');if(!svg||e.button!==0)return;mapDragged=false;mapDrag={svg,x:e.clientX,y:e.clientY,px:U.panX,py:U.panY};});
document.addEventListener('pointermove',e=>{if(!mapDrag)return;const d=mapDrag,dx=e.clientX-d.x,dy=e.clientY-d.y;if(Math.abs(dx)+Math.abs(dy)<5&&!mapDragged)return;mapDragged=true;d.svg.setPointerCapture(e.pointerId);U.panX=Math.max(-150,Math.min(150,d.px-dx*760/d.svg.getBoundingClientRect().width/U.zoom));U.panY=Math.max(-80,Math.min(80,d.py-dy*400/d.svg.getBoundingClientRect().height/U.zoom));syncMaps();});
document.addEventListener('pointerup',()=>{mapDrag=null;});document.addEventListener('pointercancel',()=>{mapDrag=null;});
document.addEventListener('click',e=>{if(mapDragged&&e.target.closest('.map')){e.stopImmediatePropagation();mapDragged=false;}},true);
const decisionLabels={adopt:'采纳方案',conditional:'有条件采纳',defer:'暂缓决策',reject:'不采纳'};
function decisionPanel(rows){
 if(U.decisionProject!==P.id||P.status==='completed'){U.decisionProject=P.id;U.decisionDraft=P.adoption?{outcome:'adopt',reviewer:'历史记录未填写',risks:'历史记录未单列，请参阅决策理由',conditions:'',reasons:[],...E.clone(P.adoption)}:null;}const d=U.decisionDraft||(U.decisionDraft={versionId:rows[0].version,outcome:'adopt',reviewer:'',note:'',risks:'',conditions:'',reasons:[]});
 if(!rows.some(r=>r.version===d.versionId))d.versionId=rows[0].version;
 const selected=rows.find(r=>r.version===d.versionId),c=B.costs(selected.run),base=E.latestRun(P,'V1'),bc=base?B.costs(base):null,delta=bc?c.construction+c.maintenance+c.rework-bc.construction-bc.maintenance-bc.rework:null;
 return `<section class="section card decision-panel"><div class="section-head"><div><div class="eyebrow">Decision review</div><h2>${icon('done')} 方案决策</h2><p>选择方案 → 说明依据与取舍 → 确认评审结论</p></div>${badge(P.adoption?'已记录采纳':'待评审')}</div><fieldset ${P.status==='completed'?'disabled':''}><legend>01 · 选择评审方案</legend><div class="grid">${rows.map(r=>`<button class="decision-option ${d.versionId===r.version?'selected':''}" data-act="decision-version" data-version="${r.version}" aria-pressed="${d.versionId===r.version}"><strong>${r.version}</strong><span>${esc(r.run.design.note)}</span><small>全周期 ${money(r.evaluation.total)}</small></button>`).join('')}</div><div class="decision-facts"><span>相对原方案投入 <b>${delta==null?'—':(delta>=0?'+':'−')+money(Math.abs(delta))}</b></span><span>保留五维取舍，不自动推荐唯一方案</span></div><legend>02 · 记录评审依据</legend><div class="decision-reasons">${D.DEFINITIONS.map(([id,name])=>`<label><input type="checkbox" data-decision-reason="${id}" ${d.reasons.includes(id)?'checked':''}>${icon(id)}${name}</label>`).join('')}</div><div class="grid two"><label>评审结论<select data-decision-field="outcome">${Object.entries(decisionLabels).map(([k,v])=>`<option value="${k}" ${d.outcome===k?'selected':''}>${v}</option>`).join('')}</select></label><label>评审人<input data-decision-field="reviewer" value="${esc(d.reviewer)}" placeholder="姓名 / 角色"></label><label>决策理由<textarea data-decision-field="note" placeholder="哪些表现支持这次结论？">${esc(d.note)}</textarea></label><label>接受的代价与保留风险<textarea data-decision-field="risks" placeholder="额外投入、尚未解决的风险或无需保留的理由">${esc(d.risks)}</textarea></label></div><label>落实条件 / 下一步要求<textarea data-decision-field="conditions" placeholder="有条件采纳、暂缓或不采纳时必填">${esc(d.conditions)}</textarea></label><div class="decision-submit"><p>采纳后可完成项目；暂缓或不采纳将保留评审记录，继续优化。</p>${btn('预览并确认结论','decision-preview','',true)}</div></fieldset>${decisionHistory()}</section>`;
}
function decisionHistory(){return (P.decisions||[]).length?`<details open class="decision-history"><summary>评审记录 · ${P.decisions.length} 次</summary>${P.decisions.slice().reverse().map(d=>`<article><strong>${esc(decisionLabels[d.outcome])} · ${esc(d.versionId)}</strong><small>${esc(d.reviewer)} · ${new Date(d.at).toLocaleString('zh-CN')}</small><p>${esc(d.note)}</p><p>保留取舍：${esc(d.risks)}</p>${d.conditions?`<p>后续要求：${esc(d.conditions)}</p>`:''}<small>依据：${d.reasons.map(id=>esc(D.DEFINITIONS.find(x=>x[0]===id)?.[1]||id)).join('、')} · 运行 ${esc(d.runId)}</small></article>`).join('')}</details>`:'';}
document.addEventListener('input',e=>{const k=e.target.dataset.decisionField;if(k&&U.decisionDraft)U.decisionDraft[k]=e.target.value;});
document.addEventListener('change',e=>{const id=e.target.dataset.decisionReason;if(id&&U.decisionDraft){const d=U.decisionDraft;d.reasons=e.target.checked?[...new Set([...d.reasons,id])]:d.reasons.filter(x=>x!==id);}const k=e.target.dataset.decisionField;if(k&&U.decisionDraft)U.decisionDraft[k]=e.target.value;});
const reviewAct=act;act=function(a,b={}){
 if(a.startsWith('decision-')&&P.status==='completed')return toast('已归档，请先继续优化');
 if(a==='decision-version'){U.decisionDraft.versionId=b.version;render();return;}
 if(a==='decision-preview'){const probe=E.clone(P);B.recordDecision(probe,U.decisionDraft);const d=U.decisionDraft;modal('确认评审结论',`<h3>${esc(d.versionId)} · ${decisionLabels[d.outcome]}</h3><p>评审人：${esc(d.reviewer)}</p><p>${esc(d.note)}</p><p>风险与代价：${esc(d.risks)}</p><p>后续要求：${esc(d.conditions||'无附加条件')}</p>`,btn('返回修改','close')+btn('确认记录','decision-confirm','',true));return;}
 if(a==='decision-confirm'){B.recordDecision(P,U.decisionDraft);close();render();toast('评审结论已记录；采纳项目可前往运行记录完成归档');return;}
 return reviewAct(a,b);
};

const reviewSummary=summary;summary=function(){return reviewSummary()+decisionHistory();};
